            "service": "anthropic",
            "model": (event["model"] as? String).map { $0 as Any } ?? NSNull(),
            "usage": usage(event["usage"]),
            "prices": prices(event["prices"]),
            "dollars": NSNull(), "unknown": NSNull(),
        ]
